blocks.code:
h1 {
  color: #1d4ed8;            /* type */
}

.card {
  background-color: #eff6ff; /* class */
  padding: 1rem;
}

a[href] {
  color: #be123c;            /* attribute: links that have an href */
}

button[type="button"] {
  font-weight: 700;          /* attribute with a value */
}

/* The paragraph that directly follows the card heading */
h2 + p {
  margin-top: 0;
  font-style: italic;
}

/* Every list item after the first one */
li + li {
  border-top: 1px solid #e2e8f0;
}

a[href^="http"]::after {
  content: " (external)";
  font-size: 0.8em;
}

a[href$=".pdf"] {
  font-weight: 700;
}

input[type="checkbox"] {
  accent-color: #1d4ed8;
}

/* Before: h1, h2 share a font */
/* h1, h2 { font-family: Georgia, serif; } */

/* After, with :is() */
:is(h1, h2) {
  font-family: Georgia, serif;
}

/* Every list item except the last */
li:not(:last-child) {
  border-bottom: 1px solid #e2e8f0;
}

/* A card that contains a button gets a stronger border */
.card:has(button) {
  border: 2px solid #1d4ed8;
  padding: 1rem;
}
